package com.ecommerce.payment.service; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*; import org.springframework.http.*; @RestController @RequestMapping("/api/payments") public class PaymentController { final PaymentRepository repo; PaymentController(PaymentRepository r){repo=r;} record Req(@NotNull UUID orderId,@NotNull @Positive BigDecimal amount,@NotBlank String idempotencyKey){} @PostMapping Payment pay(@RequestBody Req x){return repo.findByIdempotencyKey(x.idempotencyKey()).orElseGet(()->{Payment p=new Payment();p.setOrderId(x.orderId());p.setAmount(x.amount());p.setIdempotencyKey(x.idempotencyKey());return repo.save(p);});} @GetMapping("/order/{orderId}") List<Payment> byOrder(@PathVariable UUID orderId){return repo.findByOrderId(orderId);} }